package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;

public class VaultHealthActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout body;
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}build();refresh();}
 private void build(){ScrollView scroll=new ScrollView(this);LinearLayout page=Ui.column(this);page.setPadding(Ui.dp(this,20),Ui.dp(this,16),Ui.dp(this,20),Ui.dp(this,28));LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView back=Ui.text(this,"‹",40,Ui.INK);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,52)));header.addView(Ui.title(this,"Vault Health",25),new LinearLayout.LayoutParams(0,-2,1));page.addView(header);TextView intro=Ui.text(this,"See whether your encryption, recovery, backups and temporary files are in a safe state.",14,Ui.MUTED);intro.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,15));page.addView(intro);body=Ui.column(this);page.addView(body);TextView verify=Ui.pill(this,"Verify Local Vault",Ui.TEAL);verify.setOnClickListener(v->verify());LinearLayout.LayoutParams vp=new LinearLayout.LayoutParams(-1,Ui.dp(this,50));vp.topMargin=Ui.dp(this,12);page.addView(verify,vp);TextView recovery=Ui.pill(this,RecoveryKit.ready(this)?"Replace Recovery Code":"Create Recovery Code",0xff155b96);recovery.setOnClickListener(v->createRecovery());LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,Ui.dp(this,50));rp.topMargin=Ui.dp(this,10);page.addView(recovery,rp);TextView clear=Ui.pill(this,"Clear Temporary Files",0xff6b7f79);clear.setOnClickListener(v->{int n=SecureCache.clear(this);Ui.toast(this,n+" temporary file"+(n==1?"":"s")+" removed");refresh();});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,Ui.dp(this,50));cp.topMargin=Ui.dp(this,10);page.addView(clear,cp);scroll.addView(page);setContentView(scroll);}
 private void refresh(){io.execute(()->{try{JSONArray docs=new VaultRepository(this).all();int expiring=0;long horizon=System.currentTimeMillis()+90L*86400000L;SimpleDateFormat format=new SimpleDateFormat("dd/MM/yyyy",Locale.US);format.setLenient(false);for(int i=0;i<docs.length();i++){String date=docs.getJSONObject(i).optString("expiryDate");if(!date.isEmpty())try{long when=format.parse(date).getTime();if(when<=horizon)expiring++;}catch(Exception ignored){}}int finalExpiring=expiring,count=docs.length(),temp=SecureCache.count(this);SharedPreferences health=getSharedPreferences("vault-health",0);long backup=health.getLong("last_backup",0),verified=health.getLong("last_verified",0);runOnUiThread(()->render(count,finalExpiring,temp,backup,verified));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Read Vault Health"));}});}
 private void render(int count,int expiring,int temp,long backup,long verified){body.removeAllViews();row("Encryption Key",VaultKeyManager.protectedByKeystore(this)?"Protected By Android Keystore":"Protection Upgrade Pending",VaultKeyManager.protectedByKeystore(this));row("Recovery Code",RecoveryKit.ready(this)?"Ready For A Replacement Phone":"Create And Store A Recovery Code",RecoveryKit.ready(this));row("Cloud Backup",backup==0?"No Successful Backup Recorded":"Last Backup: "+date(backup),backup>0);row("Backup Verification",verified==0?"Not Verified Yet":"Verified: "+date(verified),verified>0);row("Encrypted Documents",count+" Saved",true);row("Expiry Attention",expiring==0?"Nothing Due Within 90 Days":expiring+" Due Or Expiring Soon",expiring==0);row("Temporary Files",temp==0?"Clean":temp+" Waiting For Secure Cleanup",temp==0);}
 private void row(String title,String value,boolean good){LinearLayout card=Ui.column(this);card.setPadding(Ui.dp(this,16),Ui.dp(this,13),Ui.dp(this,16),Ui.dp(this,13));card.setBackground(Ui.stroke(good?0xffeef9f5:0xfffff6e4,Ui.dp(this,1),good?0xffc6e7dc:0xffefd49d,Ui.dp(this,16)));TextView heading=Ui.title(this,(good?"✓  ":"!  ")+title,15);heading.setTextColor(good?0xff12624f:0xff8a5a00);card.addView(heading);card.addView(Ui.text(this,value,13,Ui.MUTED));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=Ui.dp(this,9);body.addView(card,p);}
 private String date(long value){return new SimpleDateFormat("dd/MM/yy · h:mm a",Locale.getDefault()).format(new Date(value));}
 private void verify(){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Authenticating every encrypted vault object…");wait.show();io.execute(()->{try{int count=new VaultRepository(this).verifyAll();runOnUiThread(()->{wait.dismiss();Ui.toast(this,count+" encrypted objects verified");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();new AlertDialog.Builder(this).setTitle("Vault Verification Failed").setMessage("One or more encrypted objects could not be authenticated. Make a fresh backup before changing anything.").setPositiveButton("OK",null).show();});}});}
 private void createRecovery(){try{String code=RecoveryKit.create(this);TextView value=Ui.text(this,code,19,Ui.NAVY);value.setTextIsSelectable(true);value.setGravity(Gravity.CENTER);value.setPadding(Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18));new AlertDialog.Builder(this).setTitle("Save Your Recovery Code").setMessage("Write this code down and keep it somewhere separate from your phone. It is required to restore My Vault on a replacement device and cannot be shown again.").setView(value).setPositiveButton("I Saved It",(d,w)->refresh()).setCancelable(false).show();}catch(Exception e){Ui.toast(this,"Could Not Create The Recovery Code");}}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
